"""Combinational RTL payload vectors generated by the independent oracle."""

from __future__ import annotations

import random
import subprocess
from pathlib import Path

from reference.mac_contract import (
    DOT_N,
    SourceFormat,
    Transaction,
    _pack_float19,
    _pack_float9,
    enter,
)


ROOT = Path(__file__).resolve().parents[3]
FP9_LANE0_MASK = (31 << 16) | 31
FP9_LANE1_MASK = (31 << 21) | (31 << 5)


def _fp9_payload(raw: int, fmt: SourceFormat, valid: int) -> int:
    mask = (FP9_LANE0_MASK if valid & 1 else 0) | (FP9_LANE1_MASK if valid & 2 else 0)
    return _pack_float9(raw, fmt) & mask


def _oracle_pair(fmt_a: SourceFormat, fmt_b: SourceFormat,
                 valid: int, raw_a: int, raw_b: int) -> tuple[int, int]:
    tx = Transaction(
        raw_a=(raw_a,) + (0,) * (DOT_N - 1),
        raw_b=(raw_b,) + (0,) * (DOT_N - 1),
        fmt_a=fmt_a, fmt_b=fmt_b,
        group_valid=valid, acc_first=valid, tag=(0, 0),
    )
    entry = enter(tx, tag_w=1)
    return entry.payload_a[0], entry.payload_b[0]


def _vector_line(fmt_a: SourceFormat, fmt_b: SourceFormat, valid: int,
                 raw_a: int, raw_b: int, expected_a: int, expected_b: int) -> str:
    return (f"{int(fmt_a):x} {int(fmt_b):x} {valid:x} "
            f"{raw_a:04x} {raw_b:04x} {expected_a:07x} {expected_b:07x}\n")


def _write_vectors(path: Path) -> int:
    count = 0
    rng = random.Random(0xA19F9)
    with path.open("w", encoding="ascii") as out:
        # Complete raw 16-bit encoding space of each FP19 source format.
        # A and B independently see every code; xor varies the paired source.
        for fmt in (SourceFormat.FP16, SourceFormat.BF16):
            for raw in range(1 << 16):
                raw_b = raw ^ 0xFFFF
                out.write(_vector_line(fmt, fmt, 1, raw, raw_b,
                                       _pack_float19(raw, fmt),
                                       _pack_float19(raw_b, fmt)))
                count += 1

        # Exhaust every FP8 byte in both physical lanes, across both source
        # decoders, including E4M3FN's exp=15 finite/NaN boundary.
        for fmt_a, fmt_b in ((SourceFormat.E4M3, SourceFormat.E5M2),
                             (SourceFormat.E5M2, SourceFormat.E4M3)):
            for byte in range(256):
                raw_a = (byte << 8) | byte
                raw_b = (((byte + 37) & 255) << 8) | ((byte + 113) & 255)
                for valid in (1, 2, 3):
                    out.write(_vector_line(fmt_a, fmt_b, valid, raw_a, raw_b,
                                           _fp9_payload(raw_a, fmt_a, valid),
                                           _fp9_payload(raw_b, fmt_b, valid)))
                    count += 1

        # Extra independent A/B and lane combinations, checked through the
        # public transaction oracle instead of the scalar decode helpers.
        for _ in range(1000):
            fmt_a, fmt_b = rng.choice(((SourceFormat.E4M3, SourceFormat.E4M3),
                                       (SourceFormat.E5M2, SourceFormat.E5M2),
                                       (SourceFormat.E4M3, SourceFormat.E5M2),
                                       (SourceFormat.E5M2, SourceFormat.E4M3)))
            raw_a, raw_b = rng.randrange(1 << 16), rng.randrange(1 << 16)
            valid = rng.choice((1, 2, 3))
            expected = _oracle_pair(fmt_a, fmt_b, valid, raw_a, raw_b)
            out.write(_vector_line(fmt_a, fmt_b, valid, raw_a, raw_b, *expected))
            count += 1

        # Legal integer encodings use the identical 26-bit payload container.
        # The reserved minimum negatives are deliberately absent.
        for _ in range(1000):
            a = rng.randint(-32767, 32767) & 0xFFFF
            b = rng.randint(-32767, 32767) & 0xFFFF
            fmt = SourceFormat.INT16
            expected = _oracle_pair(fmt, fmt, 1, a, b)
            out.write(_vector_line(fmt, fmt, 1, a, b, *expected))
            count += 1
        for fmt, width, bound in ((SourceFormat.INT8, 8, 127),
                                  (SourceFormat.INT4, 4, 7)):
            lane_mask = (1 << width) - 1
            for _ in range(1000):
                raw_a = (rng.randint(-bound, bound) & lane_mask) | ((rng.randint(-bound, bound) & lane_mask) << width)
                raw_b = (rng.randint(-bound, bound) & lane_mask) | ((rng.randint(-bound, bound) & lane_mask) << width)
                valid = rng.choice((1, 2, 3))
                expected = _oracle_pair(fmt, fmt, valid, raw_a, raw_b)
                out.write(_vector_line(fmt, fmt, valid, raw_a, raw_b, *expected))
                count += 1
    return count


def test_operand_pack_against_integer_reference(tmp_path: Path):
    vector_path = tmp_path / "operand_vectors.txt"
    image_path = tmp_path / "operand_pack.vvp"
    count = _write_vectors(vector_path)
    compile_cmd = [
        "iverilog", "-g2012", "-s", "tb_mac_operand_pack", "-o", str(image_path),
        "hardware/rtl/systemverilog/mac_types_pkg.sv", "hardware/rtl/systemverilog/mac_fp19_convert.sv",
        "hardware/rtl/systemverilog/mac_fp9_convert.sv", "hardware/rtl/systemverilog/mac_operand_pack.sv",
        "hardware/verification/tb/tb_mac_operand_pack.sv",
    ]
    compiled = subprocess.run(compile_cmd, cwd=ROOT, capture_output=True, text=True)
    assert compiled.returncode == 0, compiled.stdout + compiled.stderr
    simulated = subprocess.run(
        ["vvp", str(image_path), f"+VEC={vector_path}"],
        cwd=ROOT, capture_output=True, text=True,
    )
    assert simulated.returncode == 0, simulated.stdout + simulated.stderr
    assert f"mac_operand_pack PASS: {count} vectors" in simulated.stdout
